 * @return {number[]}
 */
var numSmallerByFrequency = function(queries, words) {
    const f = (s) => {
        let minChar = 'z';
        let count = 0;
        for (const c of s) {
            if (c < minChar) {
                minChar = c;
                count = 1;
            } else if (c === minChar) {
                count++;
