 * @return {number}
 */
var maxPoints = function(points) {
    const n = points.length;
    if (n <= 2) return n;
    function gcd(a, b) {
        a = Math.abs(a);
        b = Math.abs(b);
        while (b !== 0) {
            const temp = b;
            b = a % b;
            a = temp;
        }
        return a;
    }
    let maxCount = 1;
    for (let i = 0; i < n; i++) {
        const map = new Map();
        let localMax = 0;
        for (let j = 0; j < n; j++) {
            if (i === j) continue;
            let dx = points[j][0] - points[i][0];
            let dy = points[j][1] - points[i][1];
            const g = gcd(dx, dy);
            dx /= g;
            dy /= g;
            if (dx < 0 || (dx === 0 && dy < 0)) {
                dx = -dx;
                dy = -dy;
            }
            const key = `${dx},${dy}`;
            const count = (map.get(key) || 0) + 1;
            map.set(key, count);
            if (count > localMax) localMax = count;
        }
        if (localMax + 1 > maxCount) maxCount = localMax + 1;
    }
    return maxCount;
