 * @param {number[][]} mentors
 * @return {number}
 */
var maxCompatibilitySum = function(students, mentors) {
    const m = students.length;
    const n = students[0].length;
    const score = Array.from({ length: m }, () => Array(m).fill(0));
    for (let i = 0; i < m; i++) {
        for (let j = 0; j < m; j++) {
            for (let k = 0; k < n; k++) {
                if (students[i][k] === mentors[j][k]) score[i][j]++;
            }
        }
    }
    const dp = new Array(1 << m).fill(0);
    for (let mask = 0; mask < (1 << m); mask++) {
        const i = bitCount(mask);
        if (i >= m) continue;
        for (let j = 0; j < m; j++) {
            if ((mask & (1 << j)) === 0) {
                const next = mask | (1 << j);
                dp[next] = Math.max(dp[next], dp[mask] + score[i][j]);
            }
        }
    }
    return dp[(1 << m) - 1];
};

function bitCount(x) {
    let c = 0;
    while (x) {
        c += x & 1;
        x >>= 1;
    }
    return c;
