    const dirs = [[0,1],[1,0],[0,-1],[-1,0]];
    function countIslands() {
        const vis = Array.from({length: m}, () => Array(n).fill(false));
        let count = 0;
        function dfs(i, j) {
            vis[i][j] = true;
            for (const [di, dj] of dirs) {
                const ni = i + di, nj = j + dj;
                if (ni >= 0 && ni < m && nj >= 0 && nj < n && grid[ni][nj] === 1 && !vis[ni][nj]) {
                    dfs(ni, nj);
                }
            }
        }
        for (let i = 0; i < m; i++) {
            for (let j = 0; j < n; j++) {
                if (grid[i][j] === 1 && !vis[i][j]) {
                    count++;
                    dfs(i, j);
                }
            }
        }
        return count;
    }
    if (countIslands() !== 1) return 0;
    for (let i = 0; i < m; i++) {
        for (let j = 0; j < n; j++) {
            if (grid[i][j] === 1) {
                grid[i][j] = 0;
                if (countIslands() !== 1) {
                    grid[i][j] = 1;
                    return 1;
                }
                grid[i][j] = 1;
            }
        }
    }
