 */
var nextBeautifulNumber = function(n) {
    const beauties = [];
    const digits = [1, 2, 3, 4, 5, 6, 7];
    function generateSubsets(idx, chosen) {
        if (idx === digits.length) {
            let len = 0;
            for (const d of chosen) len += d;
            if (len === 0 || len > 7) return;
            const arr = [];
            for (const d of chosen) {
                for (let k = 0; k < d; k++) arr.push(d);
            }
            function permute(start) {
                if (start === arr.length) {
                    let num = 0;
                    for (const x of arr) num = num * 10 + x;
                    beauties.push(num);
                    return;
                }
                const used = new Set();
                for (let i = start; i < arr.length; i++) {
                    if (used.has(arr[i])) continue;
                    used.add(arr[i]);
                    [arr[start], arr[i]] = [arr[i], arr[start]];
                    permute(start + 1);
                    [arr[start], arr[i]] = [arr[i], arr[start]];
                }
            }
            permute(0);
            return;
        }
        generateSubsets(idx + 1, chosen);
        chosen.push(digits[idx]);
        generateSubsets(idx + 1, chosen);
        chosen.pop();
    }
    generateSubsets(0, []);
    beauties.sort((a, b) => a - b);
    for (const num of beauties) {
        if (num > n) return num;
