    const target = total / k;
    const N = 1 << n;
    const dp = new Array(N).fill(-1);
    dp[0] = 0;
    for (let mask = 0; mask < N; mask++) {
        if (dp[mask] === -1) continue;
        for (let i = 0; i < n; i++) {
