/**
 * @param {string} s1
 * @param {string} s2
 * @return {boolean}
 */
var isScramble = function(s1, s2) {
    const n = s1.length;
    const memo = new Map();
    function helper(i1, i2, len) {
        const key = i1 + ',' + i2 + ',' + len;
        if (memo.has(key)) return memo.get(key);
        let same = true;
        const count = new Array(26).fill(0);
        for (let k = 0; k < len; k++) {
            if (s1.charCodeAt(i1 + k) !== s2.charCodeAt(i2 + k)) same = false;
            count[s1.charCodeAt(i1 + k) - 97]++;
            count[s2.charCodeAt(i2 + k) - 97]--;
        }
        if (same) {
            memo.set(key, true);
            return true;
        }
        for (let c of count) {
            if (c !== 0) {
                memo.set(key, false);
                return false;
            }
        }
        for (let i = 1; i < len; i++) {
            if (helper(i1, i2, i) && helper(i1 + i, i2 + i, len - i)) {
                memo.set(key, true);
                return true;
            }
            if (helper(i1, i2 + len - i, i) && helper(i1 + i, i2, len - i)) {
                memo.set(key, true);
                return true;
            }
        }
        memo.set(key, false);
        return false;
    }
    return helper(0, 0, n);
};
