/**
 * @param {string[]} products
 * @param {string} searchWord
 * @return {string[][]}
 */
var suggestedProducts = function(products, searchWord) {
    products.sort();
    const n = products.length;
    const res = [];
    let prefix = "";
    const lowerBound = (target) => {
        let lo = 0, hi = n;
        while (lo < hi) {
            const mid = (lo + hi) >> 1;
            if (products[mid] < target) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    };
    for (const ch of searchWord) {
        prefix += ch;
        const start = lowerBound(prefix);
        const sugg = [];
        for (let i = start; i < Math.min(start + 3, n); i++) {
            if (products[i].startsWith(prefix)) sugg.push(products[i]);
            else break;
        }
        res.push(sugg);
    }
    return res;
};
