        push(val) {
            this.data.push(val);
            this._bubbleUp(this.data.length - 1);
        }
        pop() {
            if (this.size() === 0) return undefined;
            const top = this.data[0];
            const last = this.data.pop();
            if (this.size() > 0) {
                this.data[0] = last;
                this._bubbleDown(0);
            }
            return top;
        }
        _bubbleUp(i) {
            while (i > 0) {
                const p = (i - 1) >> 1;
                if (this.compare(this.data[i], this.data[p]) < 0) {
                    [this.data[i], this.data[p]] = [this.data[p], this.data[i]];
                    i = p;
                } else break;
            }
        }
        _bubbleDown(i) {
            const n = this.size();
            while (true) {
                let smallest = i;
                const l = 2 * i + 1, r = 2 * i + 2;
                if (l < n && this.compare(this.data[l], this.data[smallest]) < 0) smallest = l;
                if (r < n && this.compare(this.data[r], this.data[smallest]) < 0) smallest = r;
                if (smallest !== i) {
                    [this.data[i], this.data[smallest]] = [this.data[smallest], this.data[i]];
                    i = smallest;
                } else break;
            }
        }
    }

    const delayed = new Map();
    let loSize = 0, hiSize = 0;
    const lo = new Heap((a, b) => b - a);
    const hi = new Heap((a, b) => a - b);

    function prune(heap) {
        while (heap.size() > 0) {
            const num = heap.peek();
            const cnt = delayed.get(num) || 0;
            if (cnt === 0) break;
            delayed.set(num, cnt - 1);
            if (cnt - 1 === 0) delayed.delete(num);
            heap.pop();
        }
    }

    function balance() {
        prune(lo);
        prune(hi);
        if (loSize > hiSize + 1) {
            hi.push(lo.pop());
            loSize--;
            hiSize++;
            prune(lo);
        } else if (hiSize > loSize) {
            lo.push(hi.pop());
            hiSize--;
            loSize++;
            prune(hi);
        }
    }

    function add(num) {
        prune(lo);
        prune(hi);
        if (loSize === 0 || num <= lo.peek()) {
            lo.push(num);
            loSize++;
        } else {
            hi.push(num);
            hiSize++;
        }
        balance();
    }

    function remove(num) {
        prune(lo);
        prune(hi);
        delayed.set(num, (delayed.get(num) || 0) + 1);
        if (num <= lo.peek()) {
            loSize--;
        } else {
            hiSize--;
        }
        prune(lo);
        prune(hi);
        balance();
    }

    function getMedian() {
        prune(lo);
        prune(hi);
        if (k % 2 === 1) {
            return lo.peek();
        } else {
            return (lo.peek() + hi.peek()) / 2;
        }
    }

    const n = nums.length;
    const medians = [];
    for (let i = 0; i < n; i++) {
        add(nums[i]);
        if (i >= k - 1) {
            medians.push(getMedian());
            remove(nums[i - k + 1]);
        }
    }
    return medians;
};
