/**
 * @param {number[]} arr
 * @return {number[]}
 */
var sortByBits = function(arr) {
    const countBits = (n) => {
        let count = 0;
        while (n) {
            n &= n - 1;
            count++;
        }
        return count;
    };
    arr.sort((a, b) => {
        const bitsA = countBits(a);
        const bitsB = countBits(b);
        if (bitsA !== bitsB) return bitsA - bitsB;
        return a - b;
    });
    return arr;
};
