/**
 * @param {number} rows
 * @param {number} cols
 * @param {number} rStart
 * @param {number} cStart
 * @return {number[][]}
 */
var spiralMatrixIII = function(rows, cols, rStart, cStart) {
    const total = rows * cols;
    const res = [];
    let r = rStart, c = cStart;
    res.push([r, c]);
    if (total === 1) return res;
    const dr = [0, 1, 0, -1];
    const dc = [1, 0, -1, 0];
    let dir = 0;
    let k = 1;
    while (res.length < total) {
        for (let i = 0; i < 2; i++) {
            for (let j = 0; j < k; j++) {
                r += dr[dir];
                c += dc[dir];
                if (r >= 0 && r < rows && c >= 0 && c < cols) {
                    res.push([r, c]);
                    if (res.length === total) return res;
                }
            }
            dir = (dir + 1) % 4;
        }
        k++;
    }
    return res;
};
