/**
 * @param {number[]} nums
 * @param {number} k
 * @return {number}
 */
var splitArray = function(nums, k) {
    let maxNum = 0;
    let total = 0;
    for (const num of nums) {
        maxNum = Math.max(maxNum, num);
        total += num;
    }
    let left = maxNum;
    let right = total;
    const canSplit = (maxSum) => {
        let count = 1;
        let current = 0;
        for (const num of nums) {
            if (current + num > maxSum) {
                count++;
                current = num;
                if (count > k) return false;
            } else {
                current += num;
            }
        }
        return true;
    };
    while (left < right) {
        const mid = Math.floor((left + right) / 2);
        if (canSplit(mid)) {
            right = mid;
        } else {
            left = mid + 1;
        }
    }
    return left;
};
