var StreamChecker = function(words) {
    this.root = { children: {}, isEnd: false };
    this.stream = [];
    for (let word of words) {
        let node = this.root;
        for (let i = word.length - 1; i >= 0; i--) {
            let c = word[i];
            if (!node.children[c]) {
                node.children[c] = { children: {}, isEnd: false };
            }
            node = node.children[c];
        }
        node.isEnd = true;
    }
};

/** 
 * @param {character} letter
 * @return {boolean}
 */
StreamChecker.prototype.query = function(letter) {
    this.stream.push(letter);
    let node = this.root;
    for (let i = this.stream.length - 1; i >= 0; i--) {
        let c = this.stream[i];
        if (!node.children[c]) {
            return false;
        }
        node = node.children[c];
        if (node.isEnd) {
            return true;
        }
    }
    return false;
};

